---@meta ksa
-- Generated by catcom — do not edit; regenerated on every mod start.

---The catcom API. Available to every script as the global `ksa`. Reads are live. Waiting functions (`sleep`, `next_step`, ...) yield the running coroutine, so call them from `main`, a hook or a service. Write methods return a `CommandResult`; Solver-phase writes (flight-computer setpoints and debug cheats) wait for the solver slot first.
---@class ksa
---@field time ksa.Time The game clock: universal time, warp, step and frame counters, and the warp control.
---@field active ksa.VesselRef? The vessel the player currently controls, or nil when there is none.
---@field system ksa.SystemInfo The loaded planetary system: its name and the ids of its home body and sun.
---@field console ksa.Console Logging to the mod log and the in-game console, and running game console commands.
---@field state ksa.State Persistent per-script state, saved with the save game. Use `ksa.state.get(key)` and `ksa.state.set(key, value)`; plain field access (`ksa.state.counter = 1`) works too.
local ksa = {}

---Waits for the given amount of time. `ksa.sleep(2)` yields the coroutine until the time has passed.
---@async
---@param seconds number How long to wait, in seconds on the chosen clock.
---@param clock? "ut"|"wall"|"render" `"ut"` (simulation time, the default; stops while paused and scales with warp), `"wall"` (real time) or `"render"` (unscaled player frame time).
function ksa.sleep(seconds, clock) end

---Waits for the next simulation step that actually advanced (paused frames do not count) and returns its timing.
---@async
---@return ksa.StepInfo
function ksa.next_step() end

---Waits for the next rendered frame.
---@async
function ksa.next_frame() end

---Waits until `pred()` returns true. The predicate is evaluated once per step slot. Resolves true, or false when the timeout elapses first.
---@async
---@param pred fun(): boolean Returns true when the wait should end.
---@param opts? { timeout_seconds?: number, clock?: "ut"|"wall"|"render" } `timeout_seconds` gives up after that long on `clock` (default `"ut"`).
---@return boolean
function ksa.wait_until(pred, opts) end

---Waits for the next matching event and returns it, or nil when the timeout elapses first.
---@async
---@param name ksa.EventName|string The event name, e.g. `"docked"`.
---@param opts? { vessel?: string|ksa.VesselRef, timeout_seconds?: number } `vessel` restricts to one vessel (id or VesselRef); `timeout_seconds` gives up after that much simulation time.
---@return ksa.EventInfo?
function ksa.wait_event(name, opts) end

---Every vessel in the loaded system.
---@return ksa.VesselRef[]
function ksa.vessels() end

---Looks a vessel up by id; returns nil when there is no such vessel.
---@param id string The vessel id.
---@return ksa.VesselRef?
function ksa.vessel(id) end

---Every celestial body in the loaded system, as read-only data.
---@return ksa.BodyInfo[]
function ksa.bodies() end

---Looks a celestial body up by id; returns nil when there is no such body.
---@param id string The body id.
---@return ksa.BodyInfo?
function ksa.body(id) end

---Runs `handler` whenever the event fires. By default the handler runs in the next step slot and may wait; with `sync` it runs inside the game call that raised the event, under a tight time budget, and must not wait.
---@param event ksa.EventName|string The event name; see the `Events` interface for the catalog.
---@param handler fun(ctx: ksa.EventContext) Called with an EventContext; may be an async function unless `sync` is set.
---@param opts? { sync?: boolean, vessel?: string|ksa.VesselRef } `sync` runs the handler inline; `vessel` restricts the hook to one vessel (id or VesselRef).
---@return ksa.Subscription
function ksa.on(event, handler, opts) end

---Runs `handler` every frame, every landed simulation step, or every given number of seconds.
---@param kind "frame"|"step"|number `"frame"`, `"step"`, or an interval in seconds.
---@param handler fun(ctx: ksa.TickContext) Called with a TickContext; may be an async function.
---@param opts? { clock?: "ut"|"wall"|"render" } `clock` selects the clock an interval is measured on (default `"ut"`).
---@return ksa.Subscription
function ksa.every(kind, handler, opts) end

---Registers a long-running service: `fn` starts when the script loads and should loop until `ctx.signal.cancelled` becomes true.
---@param fn fun(ctx: ksa.ServiceContext) The service body; may wait freely.
---@return ksa.Subscription
function ksa.service(fn) end

---Registers a game console command that runs `fn` with the text typed after the command name.
---@param name string The console command name.
---@param fn fun(args: string) Called with the argument text.
---@param description? string One line shown in the command's help.
---@return ksa.Subscription
function ksa.command(name, fn, description) end

---Exports a function so the mod can bind it to events, ticks or a terminal (Lua scripts may instead return a table of functions; on a name clash the returned table wins).
---@param name string The export name.
---@param fn function The function to export.
function ksa.export(name, fn) end

---Every event name `ksa.on` and `ksa.wait_event` know (any other string is accepted too).
---Payload field names are snake_case in Lua.
---@alias ksa.EventName
---| "engine.activate" # An engine controller was switched on (manual, staging or script); fires at the call, before the engine physically ignites. Payload: engine.
---| "engine.deactivate" # An engine controller was switched off. Payload: engine.
---| "rcs.activate" # An RCS thruster controller was switched on or off (see payload.active). Payload: thruster, active.
---| "stage" # The vessel activated its next stage (sequence). Payload: sequence.
---| "decouple" # A decoupler fired; payload.new_vessel_id is the vessel that separated. Payload: new_vessel_id.
---| "split" # The vessel split in two (decouple, undock or debris); payload.new_vessel_id is the new vessel. Payload: new_vessel_id.
---| "dock" # Two vessels docked; vessel_id is the surviving vessel. Payload: other_vessel_id.
---| "undock" # A docking port undocked; payload.new_vessel_id is the vessel that separated. Payload: new_vessel_id.
---| "vessel.spawn" # A vessel was registered in the current system (launch, split, EVA, load). Payload: name.
---| "vessel.remove" # A vessel was deregistered from the current system (destroyed, recovered, merged). Payload: name.
---| "vessel.launch" # The vessel was marked as launched (liftoff).
---| "impact" # A ground or water impact effect was spawned. Payload: kind, body.
---| "vessel.destroy" # The vessel is about to be destroyed; payload.cause is the destruction cause or "removed". Payload: cause, peak_g, peak_q.
---| "part.failure" # One or more parts failed. Payload: parts, destroy_whole_vehicle.
---| "control.change" # The player took control of another vessel. Payload: from, to.
---| "editor.enter" # The vehicle editor opened. Payload: new_vehicle.
---| "editor.exit" # The vehicle editor closed.
---| "save.write" # A save game was written; payload.directory is its folder. Payload: directory.
---| "save.load" # A save game finished loading. Payload: directory.
---| "system.load" # A planetary system was loaded. Payload: system.
---| "warp.change" # The simulation speed (time warp) changed. Payload: from, to.
---| "burn.complete" # The flight computer finished an automatic burn.
---| "burn.fuel_out" # The flight computer stopped an automatic burn because propellant ran out; payload.stage_ran_dry is true when only the current stage ran dry and the burn stays planned for the next stage. Payload: stage_ran_dry.
---| "engine.ignite" # An engine physically ignited (differ; alias of engine-state on). Payload: engine.
---| "engine.shutdown" # An engine physically shut down (differ; alias of engine-state off). Payload: engine.
---| "soi.change" # The vessel's parent body (sphere of influence) changed. Payload: from, to.
---| "situation.change" # The vessel's situation changed (Landed, Freefall, Rolling, …): covers liftoff, landing and splashdown. Payload: from, to.
---| "flameout" # A running engine lost its propellant supply. Payload: detail, engine.
---| "battery.depleted" # The vessel's battery reached empty.
---| "battery.charged" # The vessel's battery reached full.
---| "animation.complete" # A part animation reached its goal. Payload: animation.
---| "docked" # A docking port reported docked (gatOS differ name). Payload: detail, port.
---| "undocked" # A docking port reported undocked (gatOS differ name). Payload: detail, port.
---| "decoupled" # A decoupler reported fired (gatOS differ name). Payload: detail, decoupler.
---| "active-changed" # The controlled vessel changed (gatOS differ name). Payload: detail, from, to.
---| "warp-changed" # The warp factor changed (gatOS differ name). Payload: detail, from, to.
---| "vessel-appeared" # A vessel appeared in the roster (gatOS differ name). Payload: detail, name.
---| "vessel-removed" # A vessel left the roster (gatOS differ name). Payload: detail, name.
---| "situation-change" # gatOS differ name of situation.change. Payload: detail, from, to.
---| "soi-changed" # gatOS differ name of soi.change. Payload: detail, from, to.
---| "engine-state" # An engine changed state (gatOS differ name; see engine.ignite / engine.shutdown). Payload: detail, engine, active.
---| "animation-complete" # gatOS differ name of animation.complete. Payload: detail, animation.
---| "battery-depleted" # gatOS differ name of battery.depleted. Payload: detail.
---| "battery-charged" # gatOS differ name of battery.charged. Payload: detail.
---| "term.data" # Input bytes arrived on the script's terminal (keys, mouse reports, replies). Payload: data, term_id.
---| "term.resize" # The terminal grid changed (smallest attached surface). Payload: cols, rows, term_id.
---| "term.attach" # A surface attached to the script's terminal. Payload: attached, term_id.
---| "term.detach" # A surface detached from the script's terminal. Payload: attached, term_id.
---| "term.cancel" # Ctrl+C (0x03) was pressed in the script's terminal. Payload: term_id.
---| "signal.cancel" # The script is being stopped; delivered only to that script (ctx.signal.onCancel).

---The game clock. Every property is read live from the game on access.
---@class ksa.Time
---@field ut number Universal time, in seconds.
---@field warp number The current time-warp factor.
---@field sim_dt number Duration of the last simulation step, in seconds.
---@field paused boolean Whether the simulation is paused.
---@field warp_speeds number[] The selectable warp factors.
---@field auto_warp boolean Whether automatic time warp is engaged.
---@field auto_warp_target_ut number The universal time automatic warp is heading for, in seconds (0 when none).
---@field frame number The rendered frame counter.
---@field step_index number The simulation step counter.
local Time = {}

---Sets the time-warp factor.
---Action: `debug.warp` (Frame)
---@param f number The warp factor (one of `warp_speeds`).
---@return ksa.CommandResult
function Time:set_warp(f) end

---A live handle to one vessel. It holds only the vessel id: every property read goes to the game, so values are always current, and a vessel that has vanished reads as nil or empty. Setter-style methods are named `set_x`; verbs (`ignite`, `stage`, `focus`) keep their names. Frame-phase writes return a `CommandResult`; flight-computer and debug writes are Solver-phase and wait for the solver slot.
---@class ksa.VesselRef
---@field id string The vessel id.
---@field name string The vessel's display name.
---@field situation string The flight situation (Landed, Freefall, Rolling, ...).
---@field parent string The name of the body the vessel is orbiting or standing on (empty when unknown).
---@field controlled boolean Whether this is the vessel the player controls.
---@field controllable boolean Whether the vessel can currently be controlled.
---@field is_kitten boolean Whether the vessel is a kitten (EVA crew).
---@field position ksa.Position Where the vessel is: parent-centred inertial and ecliptic positions in metres, plus latitude and longitude in degrees.
---@field velocity ksa.Velocity How fast the vessel moves: orbital, surface and inertial speeds in m/s, and the velocity vector.
---@field attitude ksa.Attitude The vessel's orientation (body to CCI quaternion) and angular rates in rad/s.
---@field altitude ksa.Altitude Barometric and radar altitude, in metres.
---@field mass ksa.Mass Total, dry and propellant mass in kilograms, and the centre of mass.
---@field orbit ksa.OrbitInfo? The current orbit, or nil when the vessel is not on one.
---@field navball ksa.NavballInfo? Navball readouts, or nil when unavailable.
---@field environment ksa.EnvironmentInfo? Atmosphere and acceleration readouts, or nil when unavailable.
---@field power ksa.Power Electrical power produced and consumed, in watts.
---@field battery ksa.Battery Battery charge fraction and capacity (both nil when the vessel has no battery).
---@field engines ksa.EngineRef[] The vessel's engines. Each entry is a snapshot with control methods; read the property again for fresh values.
---@field tanks ksa.TankInfo[] Propellant tanks by resource.
---@field rcs ksa.RcsRef[] The vessel's RCS thruster controllers.
---@field solar ksa.SolarRef[] The vessel's solar panels.
---@field generators ksa.GeneratorInfo[] The vessel's power generators.
---@field lights ksa.LightRef[] The vessel's lights.
---@field docking ksa.DockingRef[] The vessel's docking ports.
---@field decouplers ksa.DecouplerRef[] The vessel's decouplers.
---@field animations ksa.AnimationRef[] The vessel's part animations (deployables, doors, actuators).
---@field srb ksa.SrbInfo[] Solid rocket boosters with their internal ballistics.
---@field encounters ksa.EncounterInfo[] Predicted encounters with other bodies.
---@field parts ksa.PartInfo[] Every part on the vessel.
---@field throttle_cmd number The commanded throttle, 0 to 1.
---@field attitude_mode string The flight computer's attitude mode (Manual, Prograde, ...).
---@field attitude_frame string The flight computer's attitude reference frame.
---@field rcs_mode string The flight computer's RCS mode (`Enabled` or `Disabled`).
---@field rcs_on boolean Whether RCS is switched on.
---@field engine_on boolean Whether any engine is switched on.
---@field scale number The visual scale factor (1 is normal size).
---@field always_render boolean Whether the vessel is force-rendered at any distance.
---@field translate_cmd ksa.Vec3 The latched manual translation input (see translate).
---@field rotate_cmd ksa.Vec3 The latched manual rotation input (see rotate).
---@field debug ksa.VesselDebug Cheat actions: teleport, impulse, refills and taking control.
local VesselRef = {}

---Reads the complete raw snapshot record of this vessel in one call (every field the game samples, with the game's own field names).
---@return table<string, any>
function VesselRef:snapshot() end

