---Action: `vessel.stage` (Frame)
---@return ksa.CommandResult
function VesselRef:stage() end

---Sets the throttle command.
---Action: `vessel.throttle` (Frame)
---@param f number Throttle fraction, 0 to 1.
---@return ksa.CommandResult
function VesselRef:set_throttle(f) end

---Master lights switch.
---Action: `vessel.lights` (Frame)
---@param on boolean True for on, false for off.
---@return ksa.CommandResult
function VesselRef:set_lights(on) end

---Master RCS switch.
---Action: `vessel.rcs` (Frame)
---@param on boolean True for on, false for off.
